module serial2parallel (
	input clk, rst_n, din_valid, din_serial,
	output reg [7:0] dout_parallel, dout_valid
);
// Add your code here
reg [3:0] cnt;
always@(posedge clk or negedge rst_n) begin
	if(!rst_n) begin
		cnt <= 0;
		dout_parallel <= 0;
		dout_valid <= 0;
	end
	else begin
		if(din_valid && (cnt == 4'b1000)) begin
			dout_valid <= 1;
			dout_parallel <= {din_serial, dout_parallel[7:1]};
		end
		else begin
			dout_valid <= 0;
			cnt <= cnt + 1;
			dout_parallel[cnt] <= din_serial;
		end
	end
end
endmodule
